// Iterate over all panels and publish doorbell/ring to each
const panels = msg.panels || []
const idx = msg.panelIndex || 0

if (idx >= panels.length) return null

const panelId = panels[idx]
msg.topic = `dashboard/panels/${panelId}/doorbell/ring`
msg.payload = msg.ringPayload
msg.panelIndex = idx + 1

if (idx + 1 < panels.length) {
  // More panels remaining — loop back
  node.send([msg, msg])
  return null
}

// Last panel — only send to output 1 (mqtt out)
return [msg, null]
